def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    result = []
    count = 0
    group = ""

    for char in paren_string:
        if char == "(":
            count += 1
            group += char
        elif char == ")":
            count -= 1
            group += char
            if count == 0:
                result.append(group)
                group = ""

    return result

